-- ---------- Code pénal du cabinet (copie des articles de l'ancien code, sans lien avec Obsidian) ----------
create table if not exists cabinet_code_penal (
  id text primary key,
  categorie_id text not null,
  titre text not null,
  contenu text not null default '',
  amende text,
  detention text,
  niveau text,
  ordre integer not null default 0,
  created_at timestamptz not null default now()
);
alter table cabinet_code_penal enable row level security;

on conflict (id) do update set categorie_id = excluded.categorie_id, titre = excluded.titre, contenu = excluded.contenu, amende = excluded.amende, detention = excluded.detention, niveau = excluded.niveau, ordre = excluded.ordre;
