insert into cabinet_code_penal (id, categorie_id, titre, contenu, amende, detention, niveau, ordre) values
  ('DEF-1', 'penal_definitions', 'Tentative', 'La tentative correspond au cas ou l''infraction est commencee mais que cette derniere n''est pas arrivee à son terme ou n''a pas eu l''effet recherche en raison de circonstances indépendantes de la volonté de l''auteur.', null, null, null, 1),
  ('DEF-2', 'penal_definitions', 'Complicite', 'Le complice est un individu qui aide ou assiste consciemment une ou plusieurs personnes à commettre une infraction: instigation, provocation, aide, instruction.', null, null, null, 2),
  ('DEF-3', 'penal_definitions', 'Complicite apres le fait', 'Est considéré comme complice toute personne qui aide sciemment un individu à fuir ou à dissimuler des preuves suite à la commission d''infractions.', null, null, null, 3),
  ('DEF-4', 'penal_definitions', 'Possession', 'Le fait que cette possession soit dans un véhicule n''appartenant pas à la personne qui le conduit mais dont on peut raisonnablement penser qu''elle appartient a cette derniere s''expose également à cette peine.', null, null, null, 4),
  ('DEF-5', 'penal_definitions', 'Coaction', 'Est consideré comme coauteur qui réalise des elements constitutifs de l''infraction et est impliqué directement dans la réalisation de celle-ci.', null, null, null, 5),
  ('DEF-6', 'penal_definitions', 'Entreprise', 'Structure reposant sur un ou plusieurs secteurs d''activité dont l''objectif est de réaliser du chiffres d''affaires et du benefice. Elle peut etre declaree ou non declaree, mais s''expose à des sanctions pénales si ce n''est pas le cas.', null, null, null, 6),
  ('DEF-7', 'penal_definitions', 'Représentant de l''État', 'Est consideré comme un représentant de l''État un fonctionnaire agissant pour le compte de l''État et de la societé (agents de police, EMS, membres gouvernementaux, mairie, directions des services publics).', null, null, null, 7),
  ('C-1', 'penal_contravention', 'Stationnement d''un bateau sur la cote hors d''un port', 'Stationner un bateau sur une côte dépourvue de port est passible d''une amende de 450 $ et d''une mise en fourrière du bateau en infraction. Amende: 450$', '450$', null, null, 8),
  ('C-2', 'penal_contravention', 'Atterrissage d''un avion ou helicoptere sur un site inapproprié à son utilisation', 'Atterrir avec un avion ou un helicoptere sur un site non autorise pour ce type d''appareil est passible d''une amende de 450 $ et d''une mise en fourrière de l''appareil. Amende: 450$', '450$', null, null, 9),
  ('C-3', 'penal_contravention', 'Survol d''un avion ou helicoptere sur un site inapproprie a son utilisation', 'Survoler un site non autorisé en avion ou en hélicoptère est passible d''une amende de 135 $. Amende: 135$', '135$', null, null, 10),
  ('C-4', 'penal_contravention', 'Atteinte à la pudeur', 'Se déplacer nu ou en sous-vêtements dans un lieu public ou accessible au public, est passible d''une amende de 450 $. Amende: 450$', '450$', null, null, 11),
  ('C-5', 'penal_contravention', 'Conduite dangereuse en vehicule (aerien, maritime ou terrestre)', 'La conduite dangereuse, incluant le fait de ne pas maîtriser son véhicule, qu''il soit aérien, maritime ou terrestre, est passible d''une amende de 2700 $. Amende: 2700$', '2 700$', null, null, 12),
  ('C-6', 'penal_contravention', 'Dissimulation du visage', 'La dissimulation du visage dans un lieu public ou accessible au public est passible d''une amende de 540 $. Est considere comme Dissimulation du visage tout objet/masque rendant difficile l''identification des personnes. Amende: 540$', '540$', null, null, 13),
  ('C-7', 'penal_contravention', 'Exces de vitesse (controle radar)', 'Un excès de vitesse détecté par contrôle radar est passible d''une amende de 1800 $. Amende: 1800$', '1 800$', null, null, 14),
  ('C-8', 'penal_contravention', 'Grand exces de vitesse (controle radar >50km/h)', 'Un grand excès de vitesse, défini par un dépassement de plus de 50 km/h au-delà de la limite autorisée et détecté par contrôle radar, est passible d''une amende de 3 000 $ ainsi que d''un retrait de permis. Amende: 3000$', '3 000$', null, null, 15),
  ('C-9', 'penal_contravention', 'Holster interdit', 'La possession d''un holster interdit est passible d''une amende de 1 350 $. Le holster peut être saisi par les services de police. Amende: 1350$', '1 350$', null, null, 16),
  ('C-10', 'penal_contravention', 'Insulte envers un civil', 'Le fait d''insulter un civil est puni d''une amende de 270 $. Amende: 270$', '270$', null, null, 17),
  ('C-11', 'penal_contravention', 'Ivresse ou consommation de stupefiants sur la voie publique', 'Être en état d''ivresse ou consommer des stupefiants sur la voie publique est passible d''une amende de 270 $. Amende: 270$', '270$', null, null, 18),
  ('C-12', 'penal_contravention', 'Mendicite en lieu public', 'Le fait de demander de l''argent aux passants dans un lieu public est puni d''une amende de 1350$. Amende: 1350$', '1 350$', null, null, 19),
  ('C-13', 'penal_contravention', 'Non presentation des papiers d''identite', 'Le fait de ne pas présenter ses papiers d''identité à la demande d''une personne dépositaire de l''autorité publique est puni d''une amende de 450$. Amende: 450$', '450$', null, null, 20),
  ('C-14', 'penal_contravention', 'Participation a une manifestation illegale', 'Le fait de participer à une manifestation qui n''a pas été autorisée par les autorités publiques est puni d''une amende de 135$. Amende: 135$', '135$', null, null, 21),
  ('C-15', 'penal_contravention', 'Stationnement genant', 'Le fait de stationner son véhicule sur un emplacement gênant et/ou interdit est puni d''une amende de 270$. Le véhicule peut être mis en fourrière en cas d''absence de propriétaire. Amende: 270$', '270$', null, null, 22),
  ('C-16', 'penal_contravention', 'Tapage nocturne', 'Le fait de produire des nuisances sonores trop fortes le soir est puni d''une amende de 360$. Amende: 360$', '360$', null, null, 23),
  ('C-17', 'penal_contravention', 'Usage abusif du Klaxon', 'Le fait d''utiliser de manière abusive sans cadre de réel danger le klaxon d''un véhicule est puni d''une amende de 450$. Amende: 450$', '450$', null, null, 24),
  ('C-18', 'penal_contravention', 'Consommation de drogue', 'Le fait de consommer des substances classifiees comme etant des stupefiants est puni d''une amende de 450$. Toute la drogue possédée est également saisie. Amende: 450$', '450$', null, null, 25),
  ('C-19', 'penal_contravention', 'Faux appels (canulars)', 'Le fait d''appeler intentionnellement des numeros inconnus dans le but de faire une blague est puni d''une amende de 405$. Amende: 405$', '405$', null, null, 26),
  ('C-20', 'penal_contravention', 'Possession ou prise en flagrant delit de crochetage', 'La possession sur soi ou dans l''un de ses biens d''un outil de crochetage est illegale. Amende de 225$. La possession est de fait saisie. Amende: 225$', '225$', null, null, 27),
  ('C-21', 'penal_contravention', 'Conduite en contresens', 'Conduire à contresens constitue une infraction passible d''une amende de 2700 $. Amende: 2700$', '2 700$', null, null, 28),
  ('C-22', 'penal_contravention', 'Degradations de biens publics/prives/materiels', 'Le fait de porter atteinte à l''état d''un bien de manière volontaire ou involontaire est puni d''une amende de 1100$. Amende: 1100$', '1 100$', null, null, 29),
  ('C-23', 'penal_contravention', 'Vehicule non-homologue pour Cayo', 'Le fait de circuler sur l''île de Cayo Perico avec un vehicule non autorise entraîne une immobilisation du véhicule ainsi qu''une amende de 1200$. Amende: 1200$', '1 200$', null, null, 30),
  ('DM-1', 'penal_delit_mineur', 'Agression sur citoyen / maltraitance animal', 'Agresser physiquement un autre citoyen sans risque de mort est puni d''une amende de 4 500 $ et d''une detention de 30 minutes. De plus, la violence volontaire envers un animal ou un mauvais traitement est egalement sanctionnee par la même peine.', '4 500$', '30 minutes', null, 31),
  ('DM-2', 'penal_delit_mineur', 'Possession de poisson illegaux (tortues, requins, dauphin, piranha et espadons)', 'La possession de poissons classés comme illégaux sur soi, dans son véhicule ou dans ses biens est punie d''une amende de 900 $ multipliée par le nombre d''animaux détenus, ainsi que d''une détention de 10 minutes. Les animaux saisis seront saisis. Cet article n''est pas applicable sur l''île de Cayo Perico.', '900$ multipliée', '10 minutes', null, 32),
  ('DM-3', 'penal_delit_mineur', 'Outrage de base envers representant de l''etat et/ou magistrat', 'Le fait de porter atteinte à l''honneur d''un representant de l''Etat et/ou d''un magistrat dans l''exercice de ses fonctions officielles est puni d''une amende de 2 500 $. Les amendes pour outrages sont cumulables.', '2 500$', null, null, 33),
  ('DM-4', 'penal_delit_mineur', 'Appel abusif service publics', 'Le fait d''appeler de manière abusive un numero du service public sans raison valable est puni d''une amende de 1.800$ et d''un temps de détention de 15 minutes.', '1 800$', '15 minutes', null, 34),
  ('DM-5', 'penal_delit_mineur', 'Braconnage - chasse', 'Le fait de chasser illegalement est puni d''une amende de 1.350$ et d''un temps de détention de 10 minutes. Cela entraîne également un retrait du permis de chasse s''il est possédé.', '1 350$', '10 minutes', null, 35),
  ('DM-6', 'penal_delit_mineur', 'Braquage de superette/LTD', 'Le fait de voler de l''argent dans une superette par le moyen de la menace est puni d''une amende de 2250$ et d''un temps de détention de 20 minutes. L''argent liquide possédé par le délinquant est entièrement saisi.', '2 250$', '20 minutes', null, 36),
  ('DM-7', 'penal_delit_mineur', 'Braquage d''ATM / Piratage d''ATM', 'Le fait de voler de l''argent d''un ATM est puni d''une amende de 2.250$ et d''un temps de détention de 15 minutes. L''argent liquide possédé par le délinquant est entièrement saisi.', '2 250$', '15 minutes', null, 37),
  ('DM-8', 'penal_delit_mineur', 'Cambriolage', 'Le fait de s''introduire par effraction pour voler des biens dans une residence est puni d''une amende de 1.350$ et d''un temps de détention de 15 minutes. Les biens volés sont également saisis.', '1 350$', '15 minutes', null, 38),
  ('DM-9', 'penal_delit_mineur', 'Conduite sans permis', 'Le fait de conduire sans permis un véhicule en nécessitant un est puni d''une amende de 1.350$ et d''un temps de detention de 15 minutes. Le vehicule est egalement mis en fourriere si aucune personne munie d''un permis n''est présente sur place.', '1 350$', '15 minutes', null, 39),
  ('DM-10', 'penal_delit_mineur', 'Conduite d''un vehicule vole', 'Le fait de conduire un véhicule ayant été volé, est puni d''une amende de 1.350$ et d''un temps de détention de 15 minutes.', '1 350$', '15 minutes', null, 40),
  ('DM-11', 'penal_delit_mineur', 'Course de rue illegale', 'Le fait pour des individus de faire la course avec des vehicules sans qu''elle n''ait ete declarée et autorisée est puni d''une amende de 1.350$ et d''un temps de détention de 10 minutes. Les véhicules sont également mis en fourrière.', '1 350$', '10 minutes', null, 41),
  ('DM-12', 'penal_delit_mineur', 'Délit de fuite', 'Le fait de provoquer un accident et de ne pas s''arrêter est puni d''une amende de 1.350$ et d''un temps de détention de 15 minutes.', '1 350$', '15 minutes', null, 42),
  ('DM-13', 'penal_delit_mineur', 'Entrave a une operation/enquete (police/justice)', 'Le fait de gêner volontairement les forces de l''ordre en opération est puni d''une amende de 3.500$ et d''un temps de détention de 30 minutes.', '3 500$', '30 minutes', null, 43),
  ('DM-14', 'penal_delit_mineur', 'Entrave espaces aeriens', 'Le fait d''entraver volontairement un espace aerien est puni d''une amende de 900$ et d''un temps de détention de 10 minutes. L''engin est confisque et le permis aerien est retiré.', '900$', '10 minutes', null, 44),
  ('DM-15', 'penal_delit_mineur', 'Exhibition d''armes de poing', 'Le fait d''exhiber toute arme de poing est puni d''une amende de 1.350$ et d''un temps de détention de 15 minutes.', '1 350$', '15 minutes', null, 45),
  ('DM-16', 'penal_delit_mineur', 'Exhibition d''armes lourdes/automatique', 'Le fait d''exhiber toute arme lourde/automatique est puni d''une amende de 4,500$ et d''un temps de detention de 30 minutes.', '4,500$', '30 minutes', null, 46),
  ('DM-17', 'penal_delit_mineur', 'Go fast', 'Le fait d''être missionné pour rouler à très grande vitesse en transportant des marchandises illegales est puni par une amende de 2.250$ et un temps de detention de 20 minutes. Le véhicule utilisé est envoyé en fourrière.', '2 250$', '20 minutes', null, 47),
  ('DM-18', 'penal_delit_mineur', 'Utilisation illegale de drone en zone reglementee', 'Le fait d''exploiter un drone de transport en violation des zones réglementées est puni d''une amende de 12 000 $, d''un temps de détention de 20min et de la confiscation du drone.', '12 000$', null, null, 48),
  ('DM-19', 'penal_delit_mineur', 'Organisateur d''une manifestation illegale', 'L''organisateur d''une manifestation illégale est passible d''une amende de 4 100 $ et de 15 minutes.', '4 100$', null, null, 49),
  ('DM-20', 'penal_delit_mineur', 'Utilisation d''une arme a feu', 'Le fait d''avoir un test de residus de poudre positif à la suite d''une fusillade non observee par les agents, sans blesse ni deces, est puni par une amende de 1.350$ et un temps de détention de 15 minutes.', '1 350$', '15 minutes', null, 50),
  ('DM-21', 'penal_delit_mineur', 'Intrusion dans une zone a acces restreinte', 'L''intrusion dans une zone a acces restreint sans autorisation prealable est passible d''une amende de 3 200 $ et de 30 minutes.', '3 200$', null, null, 51),
  ('DM-22', 'penal_delit_mineur', 'Menace et/ou intimidation envers un civil', 'Le fait pour une personne de demontrer manifestement une intention de nuire à un civil est puni d''une amende de 3,500$ et d''un temps de détention de 15 minutes.', '3,500$', '15 minutes', null, 52),
  ('DM-23', 'penal_delit_mineur', 'Mise en danger de la vie d''autrui', 'Tout acte violant délibérément une règle de sécurité ayant comme conséquence un risque immédiat pour l''intégrité de la personne est puni d''une amende de 5.800$ et d''un temps de détention de 15 minutes.', '5 800$', '15 minutes', null, 53),
  ('DM-24', 'penal_delit_mineur', 'Non assistance a personne en danger', 'Le fait de ne pas porter assistance a une personne en besoin de secours est puni d''une amende de 4.050$ et d''un temps de détention de 20 minutes.', '4 050$', '20 minutes', null, 54),
  ('DM-25', 'penal_delit_mineur', 'Non denonciation d''un acte illegal', 'Le fait de ne pas rapporter aux autorites un crime dont on a connaissance est puni d''une amende de 2.700$ et d''un temps de détention de 15 minutes.', '2 700$', '15 minutes', null, 55),
  ('DM-26', 'penal_delit_mineur', 'Non presentation a une convocation de police', 'Le fait de ne pas se presenter à une convocation de police est puni d''une amende de 6.750$ et d''un temps de détention de 20 minutes.', '6 750$', '20 minutes', null, 56),
  ('DM-27', 'penal_delit_mineur', 'Non respect de l''assignation geographique', 'Le fait de ne pas respecter l''assignation geographique donnée dans le cadre d''une décision de justice est puni d''une amende de 18.000$ et d''un temps de détention de 10 minutes.', '18 000$', '10 minutes', null, 57),
  ('DM-28', 'penal_delit_mineur', 'Non respect du code du travail', 'Le fait pour un employeur de ne pas respecter le code du travail est puni d''une amende de 7.200$ et d''un temps de détention de 10 minutes.', '7 200$', '10 minutes', null, 58),
  ('DM-29', 'penal_delit_mineur', 'Non respect du controle judiciaire', 'Le non respect des mesures de sûreté prises à l''égard d''un individu est puni d''une amende de 2.700$ et d''un temps de détention de 10 minutes.', '2 700$', '10 minutes', null, 59),
  ('DM-30', 'penal_delit_mineur', 'Peche illegal (Espece Protegee)', 'Le fait de pêcher des espèces protégées ou avec des appâts illégaux est puni d''une amende de 3.600$ et d''un temps de detention de 10 minutes. Les espèces protégées possédées sont également saisies.', '3 600$', '10 minutes', null, 60),
  ('DM-31', 'penal_delit_mineur', 'Possession d''espèce protégée (viande, poisson)', 'Le fait de posseder une espece animale maritime protegee est puni d''une amende de 18$ multipliée par la quantité possédée et d''un temps de détention de 10 minutes.', '18$ multipliée', '10 minutes', null, 61),
  ('DM-32', 'penal_delit_mineur', 'Possession appat illegal (piranha, requin, espadon, tortue, dauphin)', 'Le fait de posséder un appat pour pecher une espèce protégée est puni d''une amende de 45$ multiplié par la quantité et d''un temps de détention de 10 minutes.', '45$', '10 minutes', null, 62),
  ('DM-33', 'penal_delit_mineur', 'Possession boîtier de piratage/ boîtier Darknet', 'La possession d''un boitier Darknet est punie d''une amende de 1.000$ et d''un temps de détention de 10 minutes.', '1 000$', '10 minutes', null, 63),
  ('DM-34', 'penal_delit_mineur', 'Possession de Canon d''arme (Pompe, fusil d''assaut, glock, lourd, pistolet, SMG)', 'La possession d''un canon d''arme est punie d''une amende de 1.500$ et d''un temps de détention de 10 minutes.', '1 500$', '10 minutes', null, 64),
  ('DM-35', 'penal_delit_mineur', 'Possession de carte fleeca / banque', 'La possession d''une carte fleeca/banque est punie d''une amende de 2.700$ et d''un temps de détention de 25 minutes.', '2 700$', '25 minutes', null, 65),
  ('DM-36', 'penal_delit_mineur', 'Port d''arme de chasse non reglementaire', 'Le port d''une arme de chasse de façon non réglementaire est puni d''une amende de 1.350$ et d''un temps de détention de 10 minutes.', '1 350$', '10 minutes', null, 66),
  ('DM-37', 'penal_delit_mineur', 'Utilisation illegale d''une arme legale', 'Utiliser une arme legale pour commettre un acte illégal est puni d''une amende de 1.500$ et de 10 minutes.', '1 500$', null, null, 67),
  ('DM-38', 'penal_delit_mineur', 'Possession de Machette', 'La possession d''une machette est punie d''une amende de 2.000$ et d''un temps de détention de 15 minutes.', '2 000$', '15 minutes', null, 68),
  ('DM-39', 'penal_delit_mineur', 'Possession de fourchette tordue', 'La possession d''une fourchette tordue est punie d''une amende de 2.000$ et d''un temps de détention de 15 minutes.', '2 000$', '15 minutes', null, 69),
  ('DM-40', 'penal_delit_mineur', 'Possession de couteau artisanal', 'La possession d''un couteau artisanal est punie d''une amende de 2.000$ et d''un temps de detention de 15 minutes.', '2 000$', '15 minutes', null, 70),
  ('DM-41', 'penal_delit_mineur', 'Possession de tesson de bouteille', 'La possession d''un tesson de bouteille est punie d''une amende de 2.000$ et d''un temps de detention de 15 minutes.', '2 000$', '15 minutes', null, 71),
  ('DM-42', 'penal_delit_mineur', 'Possession de hache', 'La possession d''une hache est punie d''une amende de 2.000$ et d''un temps de détention de 15 minutes.', '2 000$', '15 minutes', null, 72),
  ('DM-43', 'penal_delit_mineur', 'Possession de hache de guerre', 'La possession d''une hache de guerre est punie d''une amende de 2.000$ et d''un temps de détention de 15 minutes.', '2 000$', '15 minutes', null, 73),
  ('DM-44', 'penal_delit_mineur', 'Possession de dague antique', 'La possession d''une dague antique est punie d''une amende de 2.000$ et d''un temps de detention de 15 minutes.', '2 000$', '15 minutes', null, 74),
  ('DM-45', 'penal_delit_mineur', 'Possession de pistolet 17', 'La possession d''un pistolet 17 est punie d''une amende de 15.000$ et d''un temps de detention de 10 minutes.', '15 000$', '10 minutes', null, 75),
  ('DM-46', 'penal_delit_mineur', 'Possession de pistolet compact', 'La possession d''un pistolet compact est punie d''une amende de 15.000$ et d''un temps de detention de 10 minutes.', '15 000$', '10 minutes', null, 76),
  ('DM-47', 'penal_delit_mineur', 'Possession de pistolet', 'La possession d''un pistolet est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 77),
  ('DM-48', 'penal_delit_mineur', 'Possession de pistolet MXP 45', 'La possession d''un pistolet MXP 45 est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 78),
  ('DM-49', 'penal_delit_mineur', 'Possession de pistolet calibre 50', 'La possession d''un pistolet calibre 50 est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 79),
  ('DM-50', 'penal_delit_mineur', 'Possession de pistolet MKII', 'La possession d''un pistolet MKII est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 80),
  ('DM-51', 'penal_delit_mineur', 'Possession de pistolet combat', 'La possession d''un pistolet de combat (Glock) est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 81),
  ('DM-52', 'penal_delit_mineur', 'Possession de pistolet en ceramique', 'La possession d''un pistolet en céramique est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 82),
  ('DM-53', 'penal_delit_mineur', 'Possession de pistolet lourd', 'La possession d''un pistolet lourd est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 83),
  ('DM-54', 'penal_delit_mineur', 'Possession de pistolet paralysant (taser)', 'La possession d''un taser est punie d''une amende de 13.500$ et d''un temps de detention de 20 minutes.', '13 500$', '20 minutes', null, 84),
  ('DM-55', 'penal_delit_mineur', 'Possession de pistolet perforant', 'La possession d''un pistolet perforant est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 85),
  ('DM-56', 'penal_delit_mineur', 'Possession de pistolet SNS', 'La possession d''un pistolet SNS est punie d''une amende de 11.700$ et d''un temps de detention de 20 minutes.', '11 700$', '20 minutes', null, 86),
  ('DM-57', 'penal_delit_mineur', 'Possession de SNS pico', 'La possession d''un petoire est punie d''une amende de 11.700$ et d''un temps de détention de 20 minutes.', '11 700$', '20 minutes', null, 87),
  ('DM-58', 'penal_delit_mineur', 'Possession de petoire event', 'La possession d''un petoire event est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 88),
  ('DM-59', 'penal_delit_mineur', 'Possession de revolver lourd', 'La possession d''un revolver lourd est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 89),
  ('DM-60', 'penal_delit_mineur', 'Possession de revolver lourd MKII', 'La possession d''un revolver lourd MKII est punie d''une amende de 15.000$ et d''un temps de detention de 20 minutes.', '15 000$', '20 minutes', null, 90),
