  ('DM-140', 'penal_delit_mineur', 'Utilisation illegale de menottes/serflex', 'L''utilisation d''objets pour restreindre la liberté d''un individu est punie d''une amende de 120$ et d''un temps de détention de 5 minutes.', '120$', '5 minutes', null, 171),
