  ('DM-142', 'penal_delit_mineur', 'Non respect du code de commerce', 'Le non-respect du code du commerce peut entraîner une amende de 7.200$ ainsi qu''une détention de 10 minutes.', '7 200$', '10 minutes', null, 173),
