  ('DM-145', 'penal_delit_mineur', 'Non respect des consignes de l''Etat d''Urgence', 'Le non-respect des consignes lors de l''état d''urgence est puni par une amende de 4.500$ et un temps de détention de 30 minutes.', '4 500$', '30 minutes', null, 176),
  ('DM-146', 'penal_delit_mineur', 'Possession de Pistolet Artisanal', 'La possession d''un Pistolet artisanal est punie d''une amende de 15.000$ et d''un temps de détention de 20 minutes.', '15 000$', '20 minutes', null, 177),
  ('DMJ-1', 'penal_delit_majeur', 'Abus de confiance', 'Détourner au préjudice d''autrui des fonds, valeurs ou biens confiés est puni d''une amende de 12.500$ et d''une détention de 20 minutes.', '12 500$', '20 minutes', null, 178),
  ('DMJ-2', 'penal_delit_majeur', 'Braquage de societe', 'Le fait de braquer une société par la menace d''une arme est puni d''une amende de 44.000$ et d''un temps de detention de 20 minutes. Les armes et l''argent liquide sont saisis. Ce chef impose un jugement ou l''intervention d''un juge.', '44 000$', '20 minutes', null, 179),
  ('DMJ-3', 'penal_delit_majeur', 'Plagiat', 'Le plagiat est passible d''une amende de 17 500 $ et d''une détention de 30 minutes.', '17 500$', '30 minutes', null, 180),
