  ('DMJ-5', 'penal_delit_majeur', 'Attaque convoi de fonds (Brinks, Convoi SAMP)', 'Mettre en péril un convoi organisé par l''Etat est puni d''une amende de 8.500$ et d''un temps de detention de 45 minutes. Armes et argent saisis.', '8 500$', '45 minutes', null, 182),
  ('DMJ-6', 'penal_delit_majeur', 'Sollicitation ou incitation à la prostitution', 'L''incitation à la prostitution est punie par une amende de 9.000$ et un temps de détention de 1 heure.', '9 000$', '1 heure', null, 183),
  ('DMJ-7', 'penal_delit_majeur', 'Discrimination', 'Organiser une différence de traitement sur des criteres ethniques, religieux ou sexuels est puni à hauteur de 7.200$ et 20 minutes de détention.', '7 200$', null, null, 184),
  ('DMJ-8', 'penal_delit_majeur', 'Chantage', 'Le chantage est puni à hauteur de 3.150$ et 15 minutes de détention.', '3 150$', null, null, 185),
  ('DMJ-9', 'penal_delit_majeur', 'Agression sur agent (employe d''etat ou police)', 'Porter atteinte physiquement à un agent des forces de l''ordre ou employé d''Etat en service est puni à hauteur de 8.500$ et 1 heure de détention.', '8 500$', null, null, 186),
